#include <bits/stdc++.h>
using namespace std;

int main() {
    string s = "abrakadabra";
    int cnt[26] = {};
    for (char c : s) cnt[c - 'a']++;
    for (int i = 0; i < 26; i++)
        if (cnt[i]) cout << char('a' + i) << ": " << cnt[i] << '\n';
    int best = max_element(cnt, cnt + 26) - cnt;
    cout << "najczestsza: " << char('a' + best) << '\n';   // a
}

bool anagramy(const string& a, const string& b) {
    if (a.size() != b.size()) return false;
    int cnt[26] = {};
    for (char c : a) cnt[c - 'a']++;
    for (char c : b) cnt[c - 'a']--;
    for (int x : cnt) if (x != 0) return false;
    return true;
}

