#include <bits/stdc++.h>
using namespace std;

bool palindrom(const string& s) {
    for (int i = 0, j = (int)s.size() - 1; i < j; i++, j--)
        if (s[i] != s[j]) return false;
    return true;
}

// Najdłuższy spójny podpalindrom — rozszerzanie od każdego środka, O(n^2)
string najdluzszy(const string& s) {
    int n = s.size(), best = 0, start = 0;
    for (int c = 0; c < n; c++)
        for (int typ = 0; typ < 2; typ++) {          // 0: nieparzysta długość, 1: parzysta
            int l = c, r = c + typ;
            while (l >= 0 && r < n && s[l] == s[r]) { l--; r++; }
            if (r - l - 1 > best) { best = r - l - 1; start = l + 1; }
        }
    return s.substr(start, best);
}

int main() {
    cout << palindrom("kajak") << palindrom("kajaki") << '\n';   // 10
    cout << najdluzszy("abacabad") << '\n';                       // abacaba
}

