#include <bits/stdc++.h>
using namespace std;

string cezar(const string& s, int k) {
    k = ((k % 26) + 26) % 26;          // obsługa ujemnych i dużych k
    string r = s;
    for (char& c : r) {
        if (c >= 'a' && c <= 'z') c = char('a' + (c - 'a' + k) % 26);
        else if (c >= 'A' && c <= 'Z') c = char('A' + (c - 'A' + k) % 26);
    }
    return r;
}

int main() {
    string zaszyfr = cezar("Ala ma kota, xyz!", 3);
    cout << zaszyfr << '\n';            // Dod pd nrwd, abc!
    cout << cezar(zaszyfr, -3) << '\n'; // Ala ma kota, xyz!
}

